// Some portions generated by Claude
const test = require('node:test');
const assert = require('node:assert/strict');

const { createFormBrowserHarness } = require('./form-browser-harness.js');

/** The fake DOM has no firstChild/childNodes, which create.js uses when moving a row's cell content. */
function addNodeListAccessors(harness) {
    const prototype = Object.getPrototypeOf(harness.document.createElement('div'));
    if (!Object.getOwnPropertyDescriptor(prototype, 'childNodes')) {
        Object.defineProperty(prototype, 'childNodes', { get() { return this.children; }, configurable: true });
        Object.defineProperty(prototype, 'firstChild', { get() { return this.children[0] || null; },
            configurable: true });
    }
}

/** A create form with one hand-wired table row per field: [label, fieldId, role, group]. */
function createFormWithRows(fields) {
    const harness = createFormBrowserHarness();
    addNodeListAccessors(harness);
    const form = harness.registerElement('form', { attributes: { action: 'create' } });
    const table = harness.registerElement('table', { className: 'dataentry' });
    const body = harness.registerElement('tbody');
    table.appendChild(body);
    table.tBodies = [body];
    const rows = [];
    const typeRow = harness.registerElement('tr');
    body.appendChild(typeRow);
    rows.push(typeRow);
    const controls = {};
    for (const [label, fieldId, role, group] of fields) {
        const attributes = group ? { 'data-field-group': group } : {};
        const row = harness.registerElement('tr', { attributes });
        const heading = harness.registerElement('th');
        const labelElement = harness.registerElement('label', { textContent: label, attributes: { for: fieldId } });
        heading.appendChild(labelElement);
        const cell = harness.registerElement('td');
        const controlAttributes = { 'data-config-property': 'urn:p:' + fieldId };
        if (role) {
            controlAttributes['data-field-role'] = role;
        }
        const control = harness.registerElement('input', { id: fieldId, attributes: controlAttributes });
        cell.appendChild(control);
        row.appendChild(heading);
        row.appendChild(cell);
        body.appendChild(row);
        rows.push(row);
        controls[fieldId] = control;
    }
    body.rows = rows;
    form.appendChild(table);
    const create = harness.registerElement('input', { id: 'create', type: 'submit' });
    form.appendChild(create);
    harness.document.body.appendChild(form);
    harness.loadScripts(['create.js']);
    return { harness, form, table, body, controls };
}

function disclosures(root) {
    return root.querySelectorAll('[data-workbench-detail-disclosure="true"]');
}

function toggleLabel(owner) {
    return owner.querySelector('.workbench-disclosure__toggle-label').textContent;
}

const GROUPED = [
    ['Repository ID', 'rid', 'repository-id', ''],
    ['Persist', 'persist', '', ''],
    ['Sync delay', 'sync', '', 'Storage'],
    ['Cache size', 'cache', '', 'Advanced options'],
    ['Eviction', 'evict', '', 'Storage']
];

const UNGROUPED = [
    ['Repository ID', 'rid', 'repository-id', ''],
    ['Persist', 'persist', '', ''],
    ['Sync delay', 'sync', '', ''],
    ['Cache size', 'cache', '', '']
];

test('annotated groups become one disclosure per group in first-appearance order', () => {
    const { harness, table, body, controls } = createFormWithRows(GROUPED);

    harness.workbench.create.mount(harness.document.body);

    const owners = disclosures(harness.document.body);
    assert.deepEqual(Array.from(owners).map(toggleLabel), ['Storage', 'Advanced options']);
    assert.deepEqual(Array.from(owners).map((owner) => owner.id),
        ['create-group-1-disclosure', 'create-group-2-disclosure']);
    assert.equal(harness.document.getElementById('create-advanced-disclosure'), null,
        'the heuristic disclosure is not built');
    assert.equal(harness.document.querySelectorAll('.workbench-advanced__group').length, 0,
        'no word-prefix fieldsets');

    const storage = owners[0];
    assert.equal(storage.contains ? storage.contains(controls.sync) : true, true);
    assert.deepEqual(Array.from(storage.querySelectorAll('input')).map((input) => input.id), ['sync', 'evict']);
    assert.deepEqual(Array.from(owners[1].querySelectorAll('input')).map((input) => input.id), ['cache']);

    const remaining = Array.from(body.children).map((row) => row.querySelector('input'))
        .filter(Boolean).map((input) => input.id);
    assert.deepEqual(remaining, ['rid', 'persist'], 'ungrouped fields, even non-required ones, stay in the table');
    assert.equal(table.parentNode.children.includes(owners[0]), true, 'disclosures follow the table');
});

test('mounting twice does not duplicate group disclosures and cleanup releases every toggle', () => {
    const { harness } = createFormWithRows(GROUPED);

    const release = harness.workbench.create.mount(harness.document.body);
    const releaseAgain = harness.workbench.create.mount(harness.document.body);

    assert.equal(disclosures(harness.document.body).length, 2);
    const toggles = harness.document.body.querySelectorAll('.workbench-disclosure__toggle');
    assert.equal(toggles.length, 2);
    toggles.forEach((toggle) => assert.equal(toggle.getAttribute('data-workbench-bound'), 'true'));
    releaseAgain();
    release();
    toggles.forEach((toggle) => assert.notEqual(toggle.getAttribute('data-workbench-bound'), 'true'));
});

test('without any group annotation the single advanced settings disclosure is used', () => {
    const { harness } = createFormWithRows(UNGROUPED);

    harness.workbench.create.mount(harness.document.body);

    const owners = disclosures(harness.document.body);
    assert.equal(owners.length, 1);
    assert.equal(owners[0].id, 'create-advanced-disclosure');
    assert.equal(toggleLabel(owners[0]), 'Advanced settings');
    assert.deepEqual(Array.from(owners[0].querySelectorAll('input')).map((input) => input.id),
        ['persist', 'sync', 'cache']);
    assert.equal(harness.document.getElementById('create-group-1-disclosure'), null);
});
